<?php require 'config.php';require_login();if(is_admin()){header('Location: admin.php');exit;}$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND is_active=1");$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p){http_response_code(404);die('Product not found');}$page_title=$p['name'];require 'header.php';?>
<section class="wrap detail"><div><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>"></div><div><div class="eyebrow"><?=e($p['category'])?></div><h1><?=e($p['name'])?></h1><h2><?=money($p['price'])?></h2><p class="muted"><?=e($p['description'])?></p><?php if($p['stock']<1):?><p class="sold">SOLD OUT</p><?php else:?><form action="cart.php" method="post"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Choose size</label><select name="size"><?php foreach(explode(',',$p['sizes']) as $z):?><option><?=e($z)?></option><?php endforeach;?></select><label>Choose colour</label><select name="color"><?php foreach(explode(',',$p['colors']) as $c):?><option><?=e($c)?></option><?php endforeach;?></select><?php if(in_array($p['category'],['T-Shirts','Shorts','Caps'])):?><label>Custom JLB design request (optional)</label><textarea name="design" placeholder="Describe the design or placement you want"></textarea><?php endif;?><label>Quantity</label><input type="number" name="qty" min="1" max="<?=$p['stock']?>" value="1"><button>Add to cart</button></form><?php endif;?><p class="muted">Available payment options at checkout: GCash, Maya, or Cash on Delivery.</p></div></section><?php require 'footer.php';?>
